using System;
using System.Collections.Generic;
using FMODUnity;
using LittleLeo.Variables;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea.BattleActions;

public class RunesPanel : MonoBehaviour
{
	[Header("Virtues Using")]
	[SerializeField]
	private bool virtuesMoreThanOneUsePerTurn;

	[Header("Fill Animation")]
	[SerializeField]
	private float fillDuration;

	[SerializeField]
	private AnimationCurve fillCurve;

	[SerializeField]
	private float[] fillPositions;

	[SerializeField]
	private float[] fillPositionsShadow;

	[SerializeField]
	private float[] fillPositionsEffect;

	[SerializeField]
	private float[] fillPositionsPurifyEffect;

	[Header("Purify Corrupt Shake")]
	[SerializeField]
	private float corruptingShakeDuration;

	[SerializeField]
	private float corruptingShakePower;

	[SerializeField]
	private float puryfingShakeDuration;

	[SerializeField]
	private float purifyingShakePower;

	[Header("Blink")]
	[SerializeField]
	private float blinkCycleDuration;

	[SerializeField]
	private int cycles;

	[SerializeField]
	private Color corruptBlinkColor;

	[SerializeField]
	private float purifyBlinkCycleDuration;

	[SerializeField]
	private int purifyBlinkCycles;

	[SerializeField]
	private AnimationCurve purifyBlinkCurve;

	[SerializeField]
	private Color purifyBlinkColor;

	[Header("Components")]
	[SerializeField]
	private Transform corruptionGaugeTransform;

	[SerializeField]
	private Image[] corruptionGaugeImages;

	[SerializeField]
	private Image corruptionGaugeShadow;

	[SerializeField]
	private Image corruptionGaugeEffect;

	[SerializeField]
	private Image corruptionGaugeAdditive;

	[SerializeField]
	private Image purifyGaugeEffect;

	[SerializeField]
	private Image purifyGaugeAdditive;

	[SerializeField]
	private Image purifyCorruptGaugeFrameAdditive;

	[SerializeField]
	private GameObjectReference playerGameObjectReference;

	[SerializeField]
	private RuneSlot[] runeSlots;

	[SerializeField]
	private RunesPanelInitializer runesPanelInitializer;

	[Header("Assets")]
	[SerializeField]
	private PlayerCurrentRunes playerCurrentRunes;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[Header("SFX")]
	[SerializeField]
	private EventReference virtueActivatingDeactivatingSFX;

	[Header("Tutorial")]
	[SerializeField]
	private bool disableUpdateRunes;

	[SerializeField]
	private bool disableUpdateNoConditionRune;

	[NonSerialized]
	public List<RuneInstance> runeInstances = new List<RuneInstance>();

	private float playerCurrentCorruption;

	private float playerOldCorruption;

	private RunesPanelCellarius runesPanelCellarius;

	private Rune[] runes => runesPanelInitializer.Runes;

	public void SetDisableUpdateRunes(bool value)
	{
		disableUpdateRunes = value;
	}

	public void SetDisableUpdateNoConditionRune(bool value)
	{
		disableUpdateNoConditionRune = value;
	}

	public void Initialize()
	{
		InitializeMaterials();
		runesPanelCellarius = new RunesPanelCellarius();
	}

	private void InitializeMaterials()
	{
		purifyGaugeAdditive.material.SetAlpha(0f);
		purifyCorruptGaugeFrameAdditive.material.SetAlpha(0f);
		corruptionGaugeAdditive.material.SetAlpha(0f);
	}

	public void OnPlayerPurifiedCorrupted(float playerCurrentCorruption)
	{
		if (!(ReferenceSingleton<GameStateManager>.Instance.CurrentState == ReferenceSingleton<GameStateManager>.Instance.DeathState))
		{
			PlayerPurifiedCorrupted(playerCurrentCorruption);
		}
	}

	public void OnResetUsedRunes()
	{
		OnResetRandomUsedRunes();
		if (playerCurrentRunes.PlayerHaveFallenStar)
		{
			return;
		}
		playerCurrentRunes.usedRuneIndexes.Clear();
		playerCurrentRunes.refreshedRuneIndexes.AddIfNotAlreadyOnList(0);
		for (int i = 1; i < runes.Length; i++)
		{
			if (!(runeInstances[i] == null))
			{
				runeInstances[i].OnToggleActionButton(toggle: true);
				playerCurrentRunes.activeRuneIndexes.AddIfNotAlreadyOnList(i);
				playerCurrentRunes.refreshedRuneIndexes.AddIfNotAlreadyOnList(i);
			}
		}
		InvokeAlternatives.Invoke(this, 0.1f, delegate
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(virtueActivatingDeactivatingSFX);
			OnPlayerPurifiedCorrupted(playerCurrentCorruption);
		});
	}

	public void OnResetRandomUsedRunes()
	{
		if (playerCurrentRunes.PlayerHaveFallenStar)
		{
			return;
		}
		List<int> list = new List<int>();
		for (int i = 0; i < runes.Length; i++)
		{
			if (!(runeInstances[i] == null) && !runeInstances[i].ActionEnabled)
			{
				list.Add(i);
			}
		}
		if (list.Count != 0)
		{
			int num = list.PickRandom();
			playerCurrentRunes.usedRuneIndexes.Remove(num);
			runeInstances[num].OnToggleActionButton(toggle: true);
			playerCurrentRunes.activeRuneIndexes.AddIfNotAlreadyOnList(num);
			playerCurrentRunes.refreshedRuneIndexes.AddIfNotAlreadyOnList(num);
			InvokeAlternatives.Invoke(this, 0.1f, delegate
			{
				ReferenceSingleton<SFXHandler>.Instance.PlaySFX(virtueActivatingDeactivatingSFX);
				OnPlayerPurifiedCorrupted(playerCurrentCorruption);
			});
		}
	}

	private void PlayerPurifiedCorrupted(float playerCurrentCorruption)
	{
		playerOldCorruption = this.playerCurrentCorruption;
		this.playerCurrentCorruption = playerCurrentCorruption;
		if (playerCurrentCorruption == 7f)
		{
			CorruptionGaugeFeedback(playerCurrentCorruption);
		}
		else if (playerOldCorruption != playerCurrentCorruption)
		{
			CorruptionGaugeFeedback(playerCurrentCorruption);
		}
		playerCurrentRunes.currentPlayerCorruption = playerCurrentCorruption;
		float startingFill = corruptionGaugeImages[0].fillAmount;
		float targetFill = fillPositions[(int)playerCurrentCorruption];
		float corruptionGaugeShadowStartingFill = corruptionGaugeShadow.fillAmount;
		float targetFillShadow = fillPositionsShadow[(int)playerCurrentCorruption];
		float effectStartingFill = corruptionGaugeEffect.fillAmount;
		float targetFillEffect = fillPositionsEffect[(int)playerCurrentCorruption];
		float additiveStartingFill = corruptionGaugeAdditive.fillAmount;
		float purifyGaugeEffectStartingFill = purifyGaugeEffect.fillAmount;
		float targetFillPurifyEffect = fillPositionsPurifyEffect[(int)playerCurrentCorruption];
		StartCoroutine(CoroutineUtility.CurveRoutine(fillDuration, fillCurve, delegate(float t, float v)
		{
			for (int i = 0; i < corruptionGaugeImages.Length; i++)
			{
				corruptionGaugeImages[i].fillAmount = Mathf.Lerp(startingFill, targetFill, v);
			}
			corruptionGaugeShadow.fillAmount = Mathf.Lerp(corruptionGaugeShadowStartingFill, targetFillShadow, v);
			corruptionGaugeEffect.fillAmount = Mathf.Lerp(effectStartingFill, targetFillEffect, v);
			corruptionGaugeAdditive.fillAmount = Mathf.Lerp(additiveStartingFill, targetFillShadow, v);
			purifyGaugeEffect.fillAmount = Mathf.Lerp(purifyGaugeEffectStartingFill, targetFillPurifyEffect, v);
		}));
		if (!disableUpdateRunes)
		{
			UpdateRunes(playerCurrentCorruption);
		}
	}

	private void CorruptionGaugeFeedback(float playerCurrentCorruption)
	{
		float shakeDuration = corruptingShakeDuration;
		float shakePower = corruptingShakePower;
		_ = corruptBlinkColor;
		if (playerOldCorruption > playerCurrentCorruption)
		{
			shakeDuration = puryfingShakeDuration;
			shakePower = purifyingShakePower;
			_ = purifyBlinkColor;
			StartCoroutine(purifyGaugeAdditive.material.BlinkMaterial(0f, 1f, purifyBlinkCycleDuration, purifyBlinkCycles, purifyBlinkCurve));
			purifyCorruptGaugeFrameAdditive.material.SetColor("_Color", purifyBlinkColor);
			StartCoroutine(purifyCorruptGaugeFrameAdditive.material.BlinkMaterial(0f, 1f, purifyBlinkCycleDuration, purifyBlinkCycles, purifyBlinkCurve));
		}
		else
		{
			StartCoroutine(corruptionGaugeAdditive.material.BlinkMaterial(0f, 1f, blinkCycleDuration, cycles));
			purifyCorruptGaugeFrameAdditive.material.SetColor("_Color", corruptBlinkColor);
			StartCoroutine(purifyCorruptGaugeFrameAdditive.material.BlinkMaterial(0f, 1f, blinkCycleDuration, cycles));
		}
		CoroutineUtility.ShakeRoutine(this, corruptionGaugeTransform, shakeDuration, shakePower);
		CoroutineUtility.ShakeRoutine(this, base.transform, shakeDuration, shakePower);
	}

	private void UpdateRunes(float playerCurrentCorruption)
	{
		if (!disableUpdateNoConditionRune)
		{
			UpdateNoConditionRune();
		}
		bool flag = playerGameObjectReference.value.GetComponent<PlayerEffects>().IsPlayerSilenced();
		bool flag2 = playerCurrentRunes.CheckCodexOfBurdenOmen();
		bool flag3 = currentCorruptedAnimals.IsCorruptedAnimalWithSilencingAura();
		for (int i = 1; i < runes.Length; i++)
		{
			if (!(runeInstances[i] == null))
			{
				if (virtuesMoreThanOneUsePerTurn && !flag && !flag3 && !flag2 && !playerCurrentRunes.PlayerHaveFallenStar && ((float)i > playerCurrentCorruption || (float)i > playerOldCorruption))
				{
					playerCurrentRunes.usedRuneIndexes.Remove(runeInstances[i].Rune.index);
				}
				if (playerCurrentRunes.usedRuneIndexes.Contains(i))
				{
					runeSlots[i - 1].ToggleRuneSlotSprite(toggle: false);
					runeInstances[i].OnToggleActionButton(toggle: false);
				}
				else if (playerCurrentRunes.activeRuneIndexes.Contains(i))
				{
					runeInstances[i].OnToggleActionButton(toggle: true);
					runeSlots[i - 1].ToggleRuneSlotSprite(toggle: true);
				}
				else if ((float)i <= playerCurrentCorruption && (bool)runes[i].BattleAction && !playerCurrentRunes.usedRuneIndexes.Contains(runeInstances[i].Rune.index))
				{
					runeInstances[i].OnToggleActionButton(toggle: true);
					runeSlots[i - 1].ToggleRuneSlotSprite(toggle: true);
					playerCurrentRunes.activeRuneIndexes.AddIfNotAlreadyOnList(i);
				}
				else if (!playerCurrentRunes.activeRuneIndexes.Contains(i))
				{
					runeSlots[i - 1].ToggleRuneSlotSprite(toggle: false);
					runeInstances[i].OnToggleActionButton(toggle: false);
				}
			}
		}
	}

	public void UpdateNoConditionRune()
	{
		if (runes[0].BattleAction != null)
		{
			if (!playerCurrentRunes.usedRuneIndexes.Contains(0))
			{
				runeInstances[0].OnToggleActionButton(toggle: true);
				playerCurrentRunes.activeRuneIndexes.AddIfNotAlreadyOnList(0);
			}
			else
			{
				runeInstances[0].OnToggleActionButton(toggle: false);
				playerCurrentRunes.activeRuneIndexes.Remove(0);
			}
		}
	}

	public void OnUpdatePlayerCorruption()
	{
		OnPlayerPurifiedCorrupted(playerCurrentCorruption);
	}

	public void OnToggleMultipleUseRune(bool value)
	{
		virtuesMoreThanOneUsePerTurn = value;
	}

	public void ToggleRuneSlotSprite(bool toggle, int runeInstanceIndex)
	{
		if (runeInstanceIndex != 0)
		{
			runeSlots[runeInstanceIndex - 1].ToggleRuneSlotSprite(toggle);
		}
	}

	public void DisableRuneSlotSprite(int runeInstanceIndex)
	{
		if (runeInstanceIndex != 0)
		{
			int num = runeInstanceIndex - 1;
			if (num < runeSlots.Length)
			{
				runeSlots[num].DisableRuneSlotSprite();
			}
		}
	}

	public void ToggleActionValueModifierCellarius(ActionValueModifier actionValueModifier)
	{
		runesPanelCellarius.ToggleActionValueModifier(actionValueModifier, runeInstances, this, runes, playerCurrentRunes, playerCurrentCorruption);
	}
}
